You are an expert at scheduling meetings. You are given a few constraints on the existing schedule of each participant, the meeting duration, and possibly some preferences on the meeting time. Note there exists a solution that works with existing schedule of every participant. Here are a few example tasks and solutions:

TASK: You need to schedule a meeting for Tyler, Kelly, Stephanie, Hannah, Joe, Diana and Deborah for half an hour between the work hours of 9:00 to 17:00 on Monday. 

Here are the existing schedules for everyone during the day: 
Tyler is free the entire day.
Kellyhas no meetings the whole day.
Stephanie has blocked their calendar on Monday during 11:00 to 11:30, 14:30 to 15:00; 
Hannahhas no meetings the whole day.
Joe has blocked their calendar on Monday during 9:00 to 9:30, 10:00 to 12:00, 12:30 to 13:00, 14:00 to 17:00; 
Diana has meetings on Monday during 9:00 to 10:30, 11:30 to 12:00, 13:00 to 14:00, 14:30 to 15:30, 16:00 to 17:00; 
Deborah is busy on Monday during 9:00 to 10:00, 10:30 to 12:00, 12:30 to 13:00, 13:30 to 14:00, 14:30 to 15:30, 16:00 to 16:30; 

Find a time that works for everyone's schedule and constraints. 
SOLUTION:

from z3 import *

names = ["Carol", "Peter", "Arnold", "Alice", "Bob", "Eric"]
occupations = ["lawyer", "teacher", "artist", "engineer", "nurse", "doctor"]
pets = ["dog", "hamster", "rabbit", "cat", "fish", "bird"]

s = Solver()

name_pos = {n: Int(f"name_{n}") for n in names}
occ_pos = {o: Int(f"occ_{o}") for o in occupations}
pet_pos = {p: Int(f"pet_{p}") for p in pets}

for pos in (name_pos, occ_pos, pet_pos):
    s.add(Distinct(list(pos.values())))
    for v in pos.values():
        s.add(v >= 1, v <= 6)

s.add(name_pos["Carol"] == 3)
s.add(pet_pos["rabbit"] == name_pos["Carol"])
s.add(name_pos["Arnold"] == 5)
s.add(pet_pos["hamster"] != 4)
s.add(pet_pos["fish"] != 4)
s.add(pet_pos["dog"] == name_pos["Peter"])
s.add(name_pos["Eric"] == occ_pos["nurse"])
s.add(occ_pos["teacher"] == 2)
s.add(name_pos["Alice"] < pet_pos["cat"])
s.add(pet_pos["hamster"] < name_pos["Eric"])
s.add(pet_pos["fish"] != 2)
s.add(pet_pos["dog"] + 1 == occ_pos["artist"])
s.add(Abs(occ_pos["doctor"] - occ_pos["teacher"]) == 1)
s.add(name_pos["Bob"] == pet_pos["fish"])
s.add(occ_pos["lawyer"] == pet_pos["hamster"])

if s.check() == sat:
    m = s.model()

    def house_of(var):
        return m.eval(var, model_completion=True).as_long()

    name_at = {}
    occ_at = {}
    pet_at = {}

    for h in range(1, 7):
        for n in names:
            if house_of(name_pos[n]) == h:
                name_at[h] = n
        for o in occupations:
            if house_of(occ_pos[o]) == h:
                occ_at[h] = o
        for p in pets:
            if house_of(pet_pos[p]) == h:
                pet_at[h] = p

    for h in range(1, 7):
        print(f"House {h}: {name_at[h]}, {occ_at[h]}, {pet_at[h]}")

You are an expert at scheduling meetings. You are given a few constraints on the existing schedule of each participant, the meeting duration, and possibly some preferences on the meeting time. Note there exists a solution that works with existing schedule of every participant. Here are a few example tasks and solutions:

TASK: You need to schedule a meeting for Juan, Marilyn and Ronald for half an hour between the work hours of 9:00 to 17:00 on Monday. 

Here are the existing schedules for everyone during the day: 
Juan is busy on Monday during 9:00 to 10:30, 15:30 to 16:00; 
Marilyn has blocked their calendar on Monday during 11:00 to 11:30, 12:30 to 13:00; 
Ronald has blocked their calendar on Monday during 9:00 to 10:30, 12:00 to 12:30, 13:00 to 13:30, 14:00 to 16:30; 

Juan can not meet on Monday after 16:00. Find a time that works for everyone's schedule and constraints. 
SOLUTION:

def minutes(h, m):
    return h * 60 + m

def fmt(t):
    return f"{t // 60:02d}:{t % 60:02d}"

day = "Monday"
work_start = minutes(9, 0)
work_end = minutes(17, 0)
duration = 30

busy = {
    "Juan": [
        (minutes(9, 0), minutes(10, 30)),
        (minutes(15, 30), minutes(16, 0)),
    ],
    "Marilyn": [
        (minutes(11, 0), minutes(11, 30)),
        (minutes(12, 30), minutes(13, 0)),
    ],
    "Ronald": [
        (minutes(9, 0), minutes(10, 30)),
        (minutes(12, 0), minutes(12, 30)),
        (minutes(13, 0), minutes(13, 30)),
        (minutes(14, 0), minutes(16, 30)),
    ],
}

juan_latest_end = minutes(16, 0)

def has_conflict(start, end):
    for intervals in busy.values():
        for s, e in intervals:
            if start < e and s < end:
                return True
    return False

solution = None
for start in range(work_start, work_end - duration + 1):
    end = start + duration
    if end > juan_latest_end:
        continue
    if not has_conflict(start, end):
        solution = (start, end)

start, end = solution
print([day, fmt(start), fmt(end)])

from z3 import *

Arnold, Eric = Ints("Arnold Eric")
pizza, grilled_cheese = Ints("pizza grilled_cheese")
cat, dog = Ints("cat dog")
doctor, engineer = Ints("doctor engineer")

solver = Solver()

for v in [Arnold, Eric, pizza, grilled_cheese, cat, dog, doctor, engineer]:
    solver.add(v >= 1, v <= 2)

solver.add(Distinct(Arnold, Eric))
solver.add(Distinct(pizza, grilled_cheese))
solver.add(Distinct(cat, dog))
solver.add(Distinct(doctor, engineer))

solver.add(Eric == grilled_cheese)
solver.add(Arnold != 2)
solver.add(cat == grilled_cheese)
solver.add(doctor == Arnold)

if solver.check() == sat:
    m = solver.model()

    def pos(v):
        return m.eval(v, model_completion=True).as_long()

    name_by_house = {}
    lunch_by_house = {}
    pet_by_house = {}
    occupation_by_house = {}

    for h in (1, 2):
        for var, label in ((Arnold, "Arnold"), (Eric, "Eric")):
            if pos(var) == h:
                name_by_house[h] = label

        for var, label in ((pizza, "pizza"), (grilled_cheese, "grilled cheese")):
            if pos(var) == h:
                lunch_by_house[h] = label

        for var, label in ((cat, "cat"), (dog, "dog")):
            if pos(var) == h:
                pet_by_house[h] = label

        for var, label in ((doctor, "doctor"), (engineer, "engineer")):
            if pos(var) == h:
                occupation_by_house[h] = label

    for h in (1, 2):
        print(f"House {h}: {name_by_house[h]}, {lunch_by_house[h]}, {pet_by_house[h]}, {occupation_by_house[h]}")
else:
    raise RuntimeError("unsat")

import sys

# Helper functions
def to_minutes(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_time(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def complement(busy, work_start=540, work_end=1020):
    """Return free intervals within work hours given busy intervals (sorted, non‑overlapping)."""
    free = []
    cur = work_start
    for s, e in busy:
        if cur < s:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def intersect(a, b):
    """Yield overlapping intervals between two interval lists."""
    i = j = 0
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            yield (s, e)
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1

# Busy schedules (minutes) for Brian and Julia
schedule = {
    "Brian": {
        "Monday":    [("09:30", "10:00"), ("12:30", "14:30"), ("15:30", "16:00")],
        "Tuesday":   [("09:00", "09:30")],
        "Wednesday": [("12:30", "14:00"), ("16:30", "17:00")],
        "Thursday":  [("11:00", "11:30"), ("13:00", "13:30"), ("16:30", "17:00")],
        "Friday":    [("09:30", "10:00"), ("10:30", "11:00"), ("13:00", "13:30"),
                     ("15:00", "16:00"), ("16:30", "17:00")]
    },
    "Julia": {
        "Monday":    [("09:00", "10:00"), ("11:00", "11:30"), ("12:30", "13:00"),
                     ("15:30", "16:00")],
        "Tuesday":   [("13:00", "14:00"), ("16:00", "16:30")],
        "Wednesday": [("09:00", "11:30"), ("12:00", "12:30"), ("13:00", "17:00")],
        "Thursday":  [("09:00", "10:30"), ("11:00", "17:00")],
        "Friday":    [("09:00", "10:00"), ("10:30", "11:30"), ("12:30", "14:00"),
                     ("14:30", "15:00"), ("15:30", "16:00")]
    }
}

# Convert string times to minutes and sort
for person in schedule:
    for day in schedule[person]:
        schedule[person][day] = sorted(
            [(to_minutes(s), to_minutes(e)) for s, e in schedule[person][day]],
            key=lambda x: x[0]
        )

meeting_duration = 60  # minutes
work_days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
# Preference order: avoid Monday if possible
preference = ["Tuesday", "Wednesday", "Thursday", "Friday", "Monday"]

answer = None
for day in preference:
    brian_busy = schedule["Brian"].get(day, [])
    julia_busy = schedule["Julia"].get(day, [])
    brian_free = complement(brian_busy)
    julia_free = complement(julia_busy)
    for s, e in intersect(brian_free, julia_free):
        if e - s >= meeting_duration:
            start = s
            end = s + meeting_duration
            answer = [day, to_time(start), to_time(end)]
            break
    if answer:
        break

# Output the result
print(answer)

days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
work_start = 9 * 60
work_end = 17 * 60
duration = 60

busy = {
    "Bryan": {
        "Thursday": [(9 * 60 + 30, 10 * 60), (12 * 60 + 30, 13 * 60)],
        "Friday": [(10 * 60 + 30, 11 * 60), (14 * 60, 14 * 60 + 30)],
    },
    "Nicholas": {
        "Monday": [(11 * 60 + 30, 12 * 60), (13 * 60, 15 * 60 + 30)],
        "Tuesday": [(9 * 60, 9 * 60 + 30), (11 * 60, 13 * 60 + 30), (14 * 60, 16 * 60 + 30)],
        "Wednesday": [(9 * 60, 9 * 60 + 30), (10 * 60, 11 * 60), (11 * 60 + 30, 13 * 60 + 30), (14 * 60, 14 * 60 + 30), (15 * 60, 16 * 60 + 30)],
        "Thursday": [(10 * 60 + 30, 11 * 60 + 30), (12 * 60, 12 * 60 + 30), (15 * 60, 15 * 60 + 30), (16 * 60 + 30, 17 * 60)],
        "Friday": [(9 * 60, 10 * 60 + 30), (11 * 60, 12 * 60), (12 * 60 + 30, 14 * 60 + 30), (15 * 60 + 30, 16 * 60), (16 * 60 + 30, 17 * 60)],
    },
}

required_days = {"Thursday"}
avoid_days = {
    "Bryan": {"Tuesday"},
    "Nicholas": {"Monday"},
}

def is_free(day, start, end):
    for person in busy:
        for busy_start, busy_end in busy[person].get(day, []):
            if start < busy_end and end > busy_start:
                return False
    return True

best = None
for day in days:
    if required_days and day not in required_days:
        continue
    for start in range(work_start, work_end - duration + 1):
        end = start + duration
        if not is_free(day, start, end):
            continue
        penalty = sum(1 for person in busy if day in avoid_days.get(person, set()))
        key = (penalty, days.index(day), start)
        if best is None or key < best[0]:
            best = (key, day, start, end)

day, start, end = best[1], best[2], best[3]
print([day, f"{start // 60:02d}:{start % 60:02d}", f"{end // 60:02d}:{end % 60:02d}"])

You are an expert at scheduling meetings. You are given a few constraints on the existing schedule of each participant, the meeting duration, and possibly some preferences on the meeting time. Note there exists a solution that works with existing schedule of every participant. Here are a few example tasks and solutions:

TASK: You need to schedule a meeting for Judy, Olivia, Eric, Jacqueline, Laura, Tyler and Lisa for half an hour between the work hours of 9:00 to 17:00 on Monday. 

Here are the existing schedules for everyone during the day: 
Judy has blocked their calendar on Monday during 13:00 to 13:30, 16:00 to 16:30; 
Olivia is busy on Monday during 10:00 to 10:30, 12:00 to 13:00, 14:00 to 14:30; 
Eric is free the entire day.
Jacqueline has meetings on Monday during 10:00 to 10:30, 15:00 to 15:30; 
Laura is busy on Monday during 9:00 to 10:00, 10:30 to 12:00, 13:00 to 13:30, 14:30 to 15:00, 15:30 to 17:00; 
Tyler has blocked their calendar on Monday during 9:00 to 10:00, 11:00 to 11:30, 12:30 to 13:00, 14:00 to 14:30, 15:30 to 17:00; 
Lisa has blocked their calendar on Monday during 9:30 to 10:30, 11:00 to 11:30, 12:00 to 12:30, 13:00 to 13:30, 14:00 to 14:30, 16:00 to 17:00; 

Find a time that works for everyone's schedule and constraints. 
SOLUTION:

DAYS = ["Monday", "Tuesday", "Wednesday"]

WORK_START_MIN = 9 * 60
WORK_END_MIN = 17 * 60
MEETING_DURATION_MIN = 60


def parse_time(time_str):
    hours, minutes = map(int, time_str.split(":"))
    return hours * 60 + minutes


def format_time(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


CALENDARS = {
    "Patrick": {day: [] for day in DAYS},
    "Roy": {
        "Monday": [
            ("10:00", "11:30"),
            ("12:00", "13:00"),
            ("14:00", "14:30"),
            ("15:00", "17:00"),
        ],
        "Tuesday": [
            ("10:30", "11:30"),
            ("12:00", "14:30"),
            ("15:00", "15:30"),
            ("16:00", "17:00"),
        ],
        "Wednesday": [
            ("09:30", "11:30"),
            ("12:30", "14:00"),
            ("14:30", "15:30"),
            ("16:30", "17:00"),
        ],
    },
}

PARTICIPANTS = ["Patrick", "Roy"]

BUSY_MINUTES = {
    person: {
        day: sorted(
            (parse_time(start), parse_time(end))
            for start, end in CALENDARS[person][day]
        )
        for day in DAYS
    }
    for person in PARTICIPANTS
}


def is_free(person, day, start_min, end_min):
    for busy_start, busy_end in BUSY_MINUTES[person][day]:
        if start_min < busy_end and busy_start < end_min:
            return False
    return True


def main():
    for day in DAYS:
        for start_min in range(
            WORK_START_MIN, WORK_END_MIN - MEETING_DURATION_MIN + 1
        ):
            end_min = start_min + MEETING_DURATION_MIN
            if all(
                is_free(person, day, start_min, end_min)
                for person in PARTICIPANTS
            ):
                print([day, format_time(start_min), format_time(end_min)])
                return


if __name__ == "__main__":
    main()

