Harold do not want to meet on Monday after 13:00. Find a time that works for everyone's schedule and constraints. 
SOLUTION:

def to_min(hhmm):
    h, m = hhmm.split(":")
    return int(h) * 60 + int(m)


def to_hhmm(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


day = "Monday"
work_start = to_min("09:00")
work_end = to_min("17:00")
duration = 30

busy = {
    "Jacqueline": [
        (to_min("09:00"), to_min("09:30")),
        (to_min("11:00"), to_min("11:30")),
        (to_min("12:30"), to_min("13:00")),
        (to_min("15:30"), to_min("16:00")),
    ],
    "Harold": [
        (to_min("10:00"), to_min("10:30")),
        (to_min("13:00"), to_min("13:30")),
        (to_min("15:00"), to_min("17:00")),
    ],
    "Arthur": [
        (to_min("09:00"), to_min("09:30")),
        (to_min("10:00"), to_min("12:30")),
        (to_min("14:30"), to_min("15:00")),
        (to_min("15:30"), to_min("17:00")),
    ],
    "Kelly": [
        (to_min("09:00"), to_min("09:30")),
        (to_min("10:00"), to_min("11:00")),
        (to_min("11:30"), to_min("12:30")),
        (to_min("14:00"), to_min("15:00")),
        (to_min("15:30"), to_min("16:00")),
    ],
}

harold_cutoff = to_min("13:00")


def is_free(start):
    end = start + duration
    if start < work_start or end > work_end:
        return False

    for intervals in busy.values():
        for busy_start, busy_end in intervals:
            if start < busy_end and busy_start < end:
                return False

    return True


def preferred(start):
    return start <= harold_cutoff


selected = None

for start in range(work_start, work_end - duration + 1):
    if is_free(start) and preferred(start):
        selected = start
        break

if selected is None:
    for start in range(work_start, work_end - duration + 1):
        if is_free(start):
            selected = start
            break

if selected is not None:
    print([day, to_hhmm(selected), to_hhmm(selected + duration)])
else:
    print([])

