TASK: You need to schedule a meeting for Doris, Theresa, Christian, Terry, Carolyn and Kyle for half an hour between the work hours of 9:00 to 17:00 on Monday. 

Here are the existing schedules for everyone during the day: 
Doris has blocked their calendar on Monday during 9:00 to 11:00, 13:30 to 14:00, 16:00 to 16:30; 
Theresa has blocked their calendar on Monday during 10:00 to 12:00; 
Christianhas no meetings the whole day.
Terry has blocked their calendar on Monday during 9:30 to 10:00, 11:30 to 12:00, 12:30 to 13:00, 13:30 to 14:00, 14:30 to 15:00, 15:30 to 17:00; 
Carolyn has blocked their calendar on Monday during 9:00 to 10:30, 11:00 to 11:30, 12:00 to 13:00, 13:30 to 14:30, 15:00 to 17:00; 
Kyle has blocked their calendar on Monday during 9:00 to 9:30, 11:30 to 12:00, 12:30 to 13:00, 14:30 to 17:00; 

Find a time that works for everyone's schedule and constraints. 
SOLUTION:

#!/usr/bin/env python3

from datetime import datetime, timedelta

# Helper functions
def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    h = m // 60
    mm = m % 60
    return f"{h:02d}:{mm:02d}"

def complement(intervals, start, end):
    """Return free intervals within [start, end] given blocked intervals (sorted, non‑overlapping)."""
    free = []
    cur = start
    for b_start, b_end in intervals:
        if cur < b_start:
            free.append((cur, b_start))
        cur = max(cur, b_end)
    if cur < end:
        free.append((cur, end))
    return free

def intersect(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        s = max(s1, s2)
        e = min(e1, e2)
        if s < e:
            res.append((s, e))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return res

# Data
day = "Monday"
work_start = to_min("09:00")
work_end = to_min("17:00")
duration = 30  # minutes

blocked = {
    "Doris": [("09:00", "11:00"), ("13:30", "14:00"), ("16:00", "16:30")],
    "Theresa": [("10:00", "12:00")],
    "Christian": [],
    "Terry": [("09:30", "10:00"), ("11:30", "12:00"), ("12:30", "13:00"),
              ("13:30", "14:00"), ("14:30", "15:00"), ("15:30", "17:00")],
    "Carolyn": [("09:00", "10:30"), ("11:00", "11:30"), ("12:00", "13:00"),
                ("13:30", "14:30"), ("15:00", "17:00")],
    "Kyle": [("09:00", "09:30"), ("11:30", "12:00"), ("12:30", "13:00"),
             ("14:30", "17:00")]
}

# Convert blocked intervals to minutes and sort
blocked_min = {
    person: sorted((to_min(s), to_min(e)) for s, e in intervals)
    for person, intervals in blocked.items()
}

# Compute free intervals for each participant
free_intervals = {}
for person, intervals in blocked_min.items():
    free_intervals[person] = complement(intervals, work_start, work_end)

# Intersect all free intervals
people = list(free_intervals.keys())
common = free_intervals[people[0]]
for person in people[1:]:
    common = intersect(common, free_intervals[person])
    if not common:
        break

# Find earliest slot with required duration
meeting_start = None
for s, e in common:
    if e - s >= duration:
        meeting_start = s
        break

if meeting_start is None:
    raise RuntimeError("No feasible meeting time found")

meeting_end = meeting_start + duration
answer = [day, to_str(meeting_start), to_str(meeting_end)]
print(answer)

