WORK_END   = to_min('17:00')
MEETING_DURATION = 30

# Returns list of free intervals (start,end) within work hours for given busy list
def complement(busy_intervals):
    intervals = sorted(busy_intervals)
    free = []
    cur = WORK_START
    for s, e in intervals:
        if s > cur:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < WORK_END:
        free.append((cur, WORK_END))
    return free

# Intersection of two interval lists
def intersect(a, b):
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

