NAMES = ["Arnold", "Peter", "Bob", "Eric", "Alice"]
HAIR = ["gray", "brown", "black", "red", "blonde"]
VACATIONS = ["city", "mountain", "camping", "cruise", "beach"]
FLOWERS = ["roses", "tulips", "carnations", "lilies", "daffodils"]
LUNCHES = ["stew", "stir fry", "spaghetti", "pizza", "grilled cheese"]
HOBBIES = ["painting", "photography", "gardening", "knitting", "cooking"]


def check(names, hair, vacations, flowers, lunches, hobbies):
    if names[4] != "Bob":
        return False
    if flowers[2] != "lilies":
        return False
    if hobbies[3] != "knitting":
        return False
    if abs(vacations.index("cruise") - hobbies.index("knitting")) != 3:
        return False
    if lunches.index("stew") + 1 != flowers.index("tulips"):
        return False
    if vacations.index("camping") != lunches.index("grilled cheese"):
        return False
    if hair.index("black") >= names.index("Bob"):
        return False
    if hobbies.index("photography") != hair.index("gray"):
        return False
    if lunches.index("pizza") != vacations.index("cruise"):
        return False
    if names.index("Alice") != vacations.index("city"):
        return False
    if vacations.index("beach") + 1 != hobbies.index("painting"):
        return False
    if names.index("Arnold") != lunches.index("spaghetti"):
        return False
    if hair.index("brown") + 1 != hobbies.index("painting"):
        return False
    if hair.index("red") != lunches.index("spaghetti"):
        return False
    if flowers[1] == "carnations":
        return False
    if not (names.index("Eric") < hobbies.index("gardening")):
        return False
    if hobbies.index("photography") != lunches.index("stew"):
        return False
    if names.index("Eric") != flowers.index("daffodils"):
        return False
    return True


def solve():
    for names in permutations(NAMES):
        if names[4] != "Bob":
            continue

        alice = names.index("Alice")
        arnold = names.index("Arnold")
        eric = names.index("Eric")

        for hair in permutations(HAIR):
            if hair[arnold] != "red":
                continue
            if hair.index("black") >= 4:
                continue

            for vacations in permutations(VACATIONS):
                if vacations[0] != "cruise":
                    continue
                if vacations[alice] != "city":
                    continue

                for flowers in permutations(FLOWERS):
                    if flowers[2] != "lilies":
                        continue
                    if flowers[eric] != "daffodils":
                        continue
                    if flowers[1] == "carnations":
                        continue

                    for lunches in permutations(LUNCHES):
                        if lunches[0] != "pizza":
                            continue
                        if lunches[arnold] != "spaghetti":
                            continue
                        if vacations.index("camping") != lunches.index("grilled cheese"):
                            continue
                        if lunches.index("stew") + 1 != flowers.index("tulips"):
                            continue

                        for hobbies in permutations(HOBBIES):
                            if hobbies[3] != "knitting":
                                continue
                            if hobbies.index("photography") != hair.index("gray"):
                                continue
                            if hobbies.index("photography") != lunches.index("stew"):
                                continue
                            if vacations.index("beach") + 1 != hobbies.index("painting"):
                                continue
                            if hair.index("brown") + 1 != hobbies.index("painting"):
                                continue
                            if abs(vacations.index("cruise") - hobbies.index("knitting")) != 3:
                                continue
                            if not (eric < hobbies.index("gardening")):
                                continue

                            if check(names, hair, vacations, flowers, lunches, hobbies):
                                return names, hair, vacations, flowers, lunches, hobbies

    return None


solution = solve()
if solution is not None:
    names, hair, vacations, flowers, lunches, hobbies = solution
    for i in range(5):
        print(f"House {i + 1}: {names[i]}, {hair[i]}, {vacations[i]}, {flowers[i]}, {lunches[i]}, {hobbies[i]}")

import itertools

names = ['Eric', 'Arnold', 'Alice', 'Peter']
heights = ['tall', 'very short', 'average', 'short']
drinks = ['tea', 'coffee', 'water', 'milk']
children = ['Fred', 'Meredith', 'Bella', 'Samantha']
mothers = ['Holly', 'Janelle', 'Aniya', 'Kailyn']

# Helper to get house index (1‑based) of a condition
def index_of(seq, condition):
    for i, v in enumerate(seq):
        if condition(v):
            return i + 1
    return None

# Iterate over all possible assignments
for h_perm in itertools.permutations(heights):
    # Constraint 1: Arnold is tall
    # We need Arnold's house later, so postpone check
    for d_perm in itertools.permutations(drinks):
        # Constraint 3: mother Holly drinks coffee -> will check later
        for c_perm in itertools.permutations(children):
            # Constraint 2,6,14,5,10,4 will be checked later
            for m_perm in itertools.permutations(mothers):
                # Build dictionaries for quick look‑up
                house_of_name = {name: i + 1 for i, name in enumerate(names)}
                name_at = {i + 1: name for i, name in enumerate(names)}
                height_at = {i + 1: h for i, h in enumerate(h_perm)}
                drink_at = {i + 1: d for i, d in enumerate(d_perm)}
                child_at = {i + 1: c for i, c in enumerate(c_perm)}
                mother_at = {i + 1: m for i, m in enumerate(m_perm)}

                # 1. Tall is Arnold
                if height_at[house_of_name['Arnold']] != 'tall':
                    continue

                # 11. Eric is short
                if height_at[house_of_name['Eric']] != 'short':
                    continue

                # 7. Milk drinker is short
                house_milk = index_of(d_perm, lambda x: x == 'milk')
                if height_at[house_milk] != 'short':
                    continue

                # 8. Alice's child is Fred
                if child_at[house_of_name['Alice']] != 'Fred':
                    continue

                # 13. Alice's mother is Kailyn
                if mother_at[house_of_name['Alice']] != 'Kailyn':
                    continue

                # 2. Child Samantha drinks tea
                house_sam = index_of(c_perm, lambda x: x == 'Samantha')
                if drink_at[house_sam] != 'tea':
                    continue

                # 6. Child Samantha's mother is Aniya
                if mother_at[house_sam] != 'Aniya':
                    continue

                # 3. Mother Holly drinks coffee
                house_holly = index_of(m_perm, lambda x: x == 'Holly')
                if drink_at[house_holly] != 'coffee':
                    continue

                # 4. Samantha and Holly are adjacent
                if abs(house_sam - house_holly) != 1:
                    continue

                # 5. Child Meredith and very short are adjacent
                house_mer = index_of(c_perm, lambda x: x == 'Meredith')
                house_very_short = index_of(h_perm, lambda x: x == 'very short')
                if abs(house_mer - house_very_short) != 1:
                    continue

                # 9. Peter and very short are adjacent
                house_peter = house_of_name['Peter']
                if abs(house_peter - house_very_short) != 1:
                    continue

                # 10. Coffee drinker is to the right of Samantha
                house_coffee = index_of(d_perm, lambda x: x == 'coffee')
                if not (house_coffee > house_sam):
                    continue

                # 12. Mother Janelle is left of mother Kailyn
                house_janelle = index_of(m_perm, lambda x: x == 'Janelle')
                house_kailyn = index_of(m_perm, lambda x: x == 'Kailyn')
                if not (house_janelle < house_kailyn):
                    continue

                # 14. Meredith is not in the first house
                if house_mer == 1:
                    continue

                # All constraints satisfied – print solution
                for house in range(1, 5):
                    print(f"House {house}: {name_at[house]}, {height_at[house]}, {drink_at[house]}, {child_at[house]}, {mother_at[house]}")
                raise SystemExit

import itertools

names = ["Eric", "Peter", "Arnold"]
mothers = ["Holly", "Aniya", "Janelle"]
lunches = ["pizza", "grilled cheese", "spaghetti"]

def satisfies(assign):
    # assign is a list of 3 dicts for houses 0,1,2
    # Constraint 3: Eric eats grilled cheese
    for house in assign:
        if house["Name"] == "Eric" and house["Lunch"] != "grilled cheese":
            return False
    # Constraint 4: Peter's mother is Holly
    for house in assign:
        if house["Name"] == "Peter" and house["Mother"] != "Holly":
            return False
    # Constraint 1: spaghetti eater and Peter are next to each other
    pos_spaghetti = next(i for i, h in enumerate(assign) if h["Lunch"] == "spaghetti")
    pos_peter = next(i for i, h in enumerate(assign) if h["Name"] == "Peter")
    if abs(pos_spaghetti - pos_peter) != 1:
        return False
    # Constraint 2: grilled cheese is directly left of mother Aniya
    pos_grilled = next(i for i, h in enumerate(assign) if h["Lunch"] == "grilled cheese")
    pos_aniya = next(i for i, h in enumerate(assign) if h["Mother"] == "Aniya")
    if pos_grilled != pos_aniya - 1:
        return False
    return True

solutions = []
for name_perm in itertools.permutations(names):
    for mother_perm in itertools.permutations(mothers):
        for lunch_perm in itertools.permutations(lunches):
            assign = [
                {"House": i+1, "Name": name_perm[i], "Mother": mother_perm[i], "Lunch": lunch_perm[i]}
                for i in range(3)
            ]
            if satisfies(assign):
                solutions.append(assign)

# Assuming a unique solution
solution = solutions[0]
for house in solution:
    print(f"House {house['House']}: {house['Name']}, {house['Mother']}, {house['Lunch']}")

